use clap::Parser;
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Clear, Paragraph, Wrap},
    Frame, Terminal,
};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    io,
    path::{Path, PathBuf},
    process::{Command, Stdio},
    time::{Duration, Instant},
};

#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    #[arg(short, long)]
    default: Option<String>,

    #[arg(short, long)]
    out_file: Option<PathBuf>,

    #[arg(long)]
    in_file: Option<PathBuf>,

    #[arg(long)]
    config_reference: bool,

    #[arg(short, long)]
    raw_mode: bool,

    #[arg(long)]
    no_isolation: bool,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
struct Config {
    paranoid_history_mode_default: Option<bool>,
    autoeval_mode_default: Option<bool>,
    history_size: Option<usize>,
    cmdlist_always_show_preview: Option<bool>,
    cmd_timeout_millis: Option<u64>,
    highlighting_enabled: Option<bool>,
    eval_environment: Option<Vec<String>>,
    finish_hook: Option<String>,
    #[serde(default)]
    snippets: HashMap<String, String>,
    #[serde(default)]
    help_viewers: HashMap<char, String>,
    #[serde(default)]
    output_viewers: HashMap<char, String>,
}

impl Default for Config {
    fn default() -> Self {
        let mut help_viewers = HashMap::new();
        help_viewers.insert('m', "man ??".to_string());
        help_viewers.insert('h', "?? --help | less".to_string());

        let mut output_viewers = HashMap::new();
        output_viewers.insert('l', "less".to_string());

        let mut snippets = HashMap::new();
        snippets.insert("s".to_string(), " | sed -r 's/||//g'".to_string());

        Config {
            paranoid_history_mode_default: Some(false),
            autoeval_mode_default: Some(true),
            history_size: Some(500),
            cmdlist_always_show_preview: Some(false),
            cmd_timeout_millis: Some(2000),
            highlighting_enabled: Some(true),
            eval_environment: Some(vec!["bash".to_string(), "-c".to_string()]),
            finish_hook: None,
            snippets,
            help_viewers,
            output_viewers,
        }
    }
}

enum ActiveMenu {
    Main,
    Help,
    History,
    Bookmarks,
    Snippets,
    HelpViewers,
    OutputViewers,
}

struct App {
    command: String,
    cursor_pos: usize,
    autoeval: bool,
    paranoid_history: bool,
    history: Vec<String>,
    history_index: Option<usize>,
    bookmarks: Vec<String>,
    stdout: String,
    stderr: String,
    exit_code: Option<i32>,
    last_eval: Instant,
    config: Config,
    active_menu: ActiveMenu,
    cached_output: Option<String>,
    cached_pipe_index: Option<usize>,
    spinner_index: usize,
    is_running: bool,
}

impl App {
    fn new(config: Config, initial_cmd: String) -> Self {
        App {
            command: initial_cmd,
            cursor_pos: 0,
            autoeval: config.autoeval_mode_default.unwrap_or(true),
            paranoid_history: config.paranoid_history_mode_default.unwrap_or(false),
            history: Vec::new(),
            history_index: None,
            bookmarks: Vec::new(),
            stdout: String::new(),
            stderr: String::new(),
            exit_code: Some(0),
            last_eval: Instant::now(),
            config,
            active_menu: ActiveMenu::Main,
            cached_output: None,
            cached_pipe_index: None,
            spinner_index: 0,
            is_running: false,
        }
    }

    fn evaluate(&mut self) {
        let cmd_to_run = self.command.lines()
            .filter(|line| !line.trim().starts_with('#'))
            .collect::<Vec<_>>()
            .join(" ");

        if cmd_to_run.is_empty() {
            self.stdout = String::new();
            self.stderr = String::new();
            self.exit_code = Some(0);
            return;
        }

        let eval_env = self.config.eval_environment.clone().unwrap_or_else(|| vec!["bash".to_string(), "-c".to_string()]);

        let mut child = Command::new(&eval_env[0])
            .args(&eval_env[1..])
            .arg(&cmd_to_run)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .expect("Failed to execute command");

        let output = child.wait_with_output().expect("Failed to wait on child");
        self.stdout = String::from_utf8_lossy(&output.stdout).to_string();
        self.stderr = String::from_utf8_lossy(&output.stderr).to_string();
        self.exit_code = output.status.code();
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    if args.config_reference {
        let default_config = Config::default();
        println!("{}", toml::to_string(&default_config)?);
        return Ok(());
    }

    let config = load_config().unwrap_or_default();

    let initial_cmd = if let Some(in_file) = args.in_file {
        fs::read_to_string(in_file).unwrap_or_default()
    } else {
        args.default.unwrap_or_default()
    };

    let mut app = App::new(config, initial_cmd);
    app.cursor_pos = app.command.len();
    load_history(&mut app);
    load_bookmarks(&mut app);

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let res = run_app(&mut terminal, app, args.out_file, args.raw_mode);

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        println!("{:?}", err);
    }

    Ok(())
}

fn load_config() -> Option<Config> {
    let config_path = dirs::config_dir()?.join("pipr").join("pipr.toml");
    if config_path.exists() {
        let content = fs::read_to_string(config_path).ok()?;
        toml::from_str(&content).ok()
    } else {
        None
    }
}

fn load_history(app: &mut App) {
    if let Some(config_dir) = dirs::config_dir() {
        let history_path = config_dir.join("pipr").join("history");
        if history_path.exists() {
            if let Ok(content) = fs::read_to_string(history_path) {
                app.history = content.split("\n---\n").map(|s| s.to_string()).filter(|s| !s.is_empty()).collect();
            }
        }
    }
}

fn save_history(app: &App) {
    if let Some(config_dir) = dirs::config_dir() {
        let history_dir = config_dir.join("pipr");
        let _ = fs::create_dir_all(&history_dir);
        let history_path = history_dir.join("history");
        let content = app.history.join("\n---\n");
        let _ = fs::write(history_path, content);
    }
}

fn load_bookmarks(app: &mut App) {
    if let Some(config_dir) = dirs::config_dir() {
        let bookmarks_path = config_dir.join("pipr").join("bookmarks");
        if bookmarks_path.exists() {
            if let Ok(content) = fs::read_to_string(bookmarks_path) {
                app.bookmarks = content.lines().map(|s| s.to_string()).collect();
            }
        }
    }
}

fn save_bookmarks(app: &App) {
    if let Some(config_dir) = dirs::config_dir() {
        let history_dir = config_dir.join("pipr");
        let _ = fs::create_dir_all(&history_dir);
        let bookmarks_path = history_dir.join("bookmarks");
        let content = app.bookmarks.join("\n");
        let _ = fs::write(bookmarks_path, content);
    }
}

fn run_app<B: Backend>(
    terminal: &mut Terminal<B>,
    mut app: App,
    out_file: Option<PathBuf>,
    raw_mode: bool,
) -> io::Result<()> {
    loop {
        if app.autoeval {
            app.evaluate();
        }

        terminal.draw(|f| ui(f, &app))?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match app.active_menu {
                    ActiveMenu::Main => {
                        match key.code {
                            KeyCode::Esc => {
                                if let Some(path) = out_file {
                                    let mut cmd = app.command.clone();
                                    if !raw_mode {
                                        cmd = cmd.replace("\n", " ");
                                    }
                                    let _ = fs::write(path, cmd);
                                }
                                if let Some(hook) = &app.config.finish_hook {
                                    let mut child = Command::new("bash")
                                        .arg("-c")
                                        .arg(hook)
                                        .stdin(Stdio::piped())
                                        .spawn()
                                        .ok();
                                    if let Some(mut child) = child {
                                        use std::io::Write;
                                        if let Some(mut stdin) = child.stdin.take() {
                                            let _ = stdin.write_all(app.command.as_bytes());
                                        }
                                        let _ = child.wait();
                                    }
                                }
                                // Add to history before exiting
                                if !app.command.trim().is_empty() {
                                    app.history.push(app.command.clone());
                                    save_history(&app);
                                }
                                return Ok(());
                            }
                            KeyCode::Char(c) => {
                                if key.modifiers.contains(KeyModifiers::CONTROL) {
                                    match c {
                                        's' => {
                                            app.bookmarks.push(app.command.clone());
                                            save_bookmarks(&app);
                                        }
                                        'b' => app.active_menu = ActiveMenu::Bookmarks,
                                        'v' => app.active_menu = ActiveMenu::Snippets,
                                        'p' => {
                                            // Previous history
                                        }
                                        'n' => {
                                            // Next history
                                        }
                                        'u' => {
                                            app.command.clear();
                                            app.cursor_pos = 0;
                                        }
                                        _ => {}
                                    }
                                } else {
                                    app.command.insert(app.cursor_pos, c);
                                    app.cursor_pos += 1;
                                }
                            }
                            KeyCode::Backspace => {
                                if app.cursor_pos > 0 {
                                    app.cursor_pos -= 1;
                                    app.command.remove(app.cursor_pos);
                                }
                            }
                            KeyCode::Delete => {
                                if app.cursor_pos < app.command.len() {
                                    app.command.remove(app.cursor_pos);
                                }
                            }
                            KeyCode::Left => {
                                if app.cursor_pos > 0 {
                                    app.cursor_pos -= 1;
                                }
                            }
                            KeyCode::Right => {
                                if app.cursor_pos < app.command.len() {
                                    app.cursor_pos += 1;
                                }
                            }
                            KeyCode::Enter => {
                                if key.modifiers.contains(KeyModifiers::ALT) {
                                    app.command.insert(app.cursor_pos, '\n');
                                    app.cursor_pos += 1;
                                } else {
                                    app.evaluate();
                                }
                            }
                            KeyCode::F(1) => app.active_menu = ActiveMenu::Help,
                            KeyCode::F(2) => app.autoeval = !app.autoeval,
                            KeyCode::F(4) => app.active_menu = ActiveMenu::History,
                            _ => {}
                        }
                    }
                    _ => {
                        if key.code == KeyCode::Esc || key.code == KeyCode::F(1) || key.code == KeyCode::F(4) {
                            app.active_menu = ActiveMenu::Main;
                        }
                    }
                }
            }
        }
    }
}

fn ui(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(app.command.lines().count() as u64 + 2),
            Constraint::Min(0),
        ].as_ref())
        .split(f.size());

    let mut command_title = " Command ".to_string();
    if app.autoeval {
        command_title.push_str("[Autoeval] ");
    }
    if app.cached_pipe_index.is_some() {
        command_title.push_str("[Caching] ");
    }

    let command_block = Block::default().borders(Borders::ALL).title(command_title);
    let command_p = Paragraph::new(app.command.as_str()).block(command_block);
    f.render_widget(command_p, chunks[0]);

    // Draw cursor
    let lines = app.command.lines().collect::<Vec<_>>();
    let mut cursor_y = 0;
    let mut cursor_x = 0;
    let mut remaining_pos = app.cursor_pos;
    for (i, line) in lines.iter().enumerate() {
        if remaining_pos <= line.len() {
            cursor_y = i;
            cursor_x = remaining_pos;
            break;
        }
        remaining_pos -= line.len() + 1;
    }
    f.set_cursor(chunks[0].x + 1 + cursor_x as u16, chunks[0].y + 1 + cursor_y as u16);

    let output_chunks = if app.exit_code != Some(0) && !app.stderr.is_empty() {
        Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Percentage(50), Constraint::Percentage(50)].as_ref())
            .split(chunks[1])
    } else {
        vec![chunks[1]]
    };

    let output_block = Block::default().borders(Borders::ALL).title(" Output ");
    let output_p = Paragraph::new(app.stdout.as_str()).block(output_block).wrap(Wrap { trim: false });
    f.render_widget(output_p, output_chunks[0]);

    if output_chunks.len() > 1 {
        let stderr_block = Block::default().borders(Borders::ALL).title(" Stderr ");
        let stderr_p = Paragraph::new(app.stderr.as_str()).block(stderr_block).wrap(Wrap { trim: false });
        f.render_widget(stderr_p, output_chunks[1]);
    }

    // Help text at the bottom right
    let help_text = "Help: F1";
    let help_area = Rect::new(f.size().width - help_text.len() as u16 - 2, f.size().height - 1, help_text.len() as u16 + 2, 1);
    f.render_widget(Paragraph::new(help_text), help_area);

    match app.active_menu {
        ActiveMenu::Help => {
            let area = centered_rect(60, 60, f.size());
            let help_block = Block::default().borders(Borders::ALL).title(" Help ");
            let help_content = "F1         Show/hide help\nF2         Toggle autoeval\nF4         Show/hide history\n...";
            let p = Paragraph::new(help_content).block(help_block);
            f.render_widget(Clear, area);
            f.render_widget(p, area);
        }
        ActiveMenu::History => {
            let area = centered_rect(80, 80, f.size());
            let hist_block = Block::default().borders(Borders::ALL).title(" History ");
            let hist_content = app.history.join("\n---\n");
            let p = Paragraph::new(hist_content).block(hist_block);
            f.render_widget(Clear, area);
            f.render_widget(p, area);
        }
        _ => {}
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ].as_ref())
        .split(r);

    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ].as_ref())
        .split(popup_layout[1])[1]
}
