        self.stdout = String::from_utf8_lossy(&output.stdout).to_string();
        self.stderr = String::from_utf8_lossy(&output.stderr).to_string();
        self.exit_code = output.status.code();
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();
    if args.config_reference {
        println!("{}", toml::to_string(&Config::default())?);
        return Ok(());
    }
    let config = load_config().unwrap_or_default();
    let initial_cmd = if let Some(in_file) = args.in_file {
        fs::read_to_string(in_file).unwrap_or_default()
    } else {
        args.default.unwrap_or_default()
    };
    let mut app = App::new(config, initial_cmd, args.no_isolation);
    app.cursor_pos = app.command.len();
    load_history(&mut app);
    load_bookmarks(&mut app);

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let res = run_app(&mut terminal, app, args.out_file, args.raw_mode);

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen, DisableMouseCapture)?;
    terminal.show_cursor()?;
