    let content = fs::read_to_string(path).ok()?;
    toml::from_str(&content).ok()
}

fn load_history(app: &mut App) {
    if let Some(dir) = dirs::config_dir() {
        let path = dir.join("pipr").join("history");
        if let Ok(content) = fs::read_to_string(path) {
            app.history = content.split("\n---\n").map(|s| s.to_string()).filter(|s| !s.is_empty()).collect();
        }
    }
}

fn save_history(app: &App) {
    if let Some(dir) = dirs::config_dir() {
        let _ = fs::create_dir_all(dir.join("pipr"));
        let _ = fs::write(dir.join("pipr").join("history"), app.history.join("\n---\n"));
    }
}

fn load_bookmarks(app: &mut App) {
