                        KeyCode::Char(c) => { app.command.insert(app.cursor_pos, c); app.cursor_pos += 1; }
                        KeyCode::Backspace => { if app.cursor_pos > 0 { app.cursor_pos -= 1; app.command.remove(app.cursor_pos); } }
                        KeyCode::Delete => { if app.cursor_pos < app.command.len() { app.command.remove(app.cursor_pos); } }
                        KeyCode::Left => { if app.cursor_pos > 0 { app.cursor_pos -= 1; } }
                        KeyCode::Right => { if app.cursor_pos < app.command.len() { app.cursor_pos += 1; } }
                        KeyCode::Enter => {
                            if key.modifiers.contains(KeyModifiers::ALT) {
                                app.command.insert(app.cursor_pos, '\n'); app.cursor_pos += 1;
                            } else {
                                app.evaluate();
                            }
                        }
                        KeyCode::F(1) => app.active_menu = ActiveMenu::Help,
                        KeyCode::F(2) => app.autoeval = !app.autoeval,
                        KeyCode::F(4) => { app.active_menu = ActiveMenu::History; app.list_state.select(Some(0)); }
                        KeyCode::F(5) => app.active_menu = ActiveMenu::HelpViewers,
                        KeyCode::F(6) => app.active_menu = ActiveMenu::OutputViewers,
                        KeyCode::F(7) => {
                            // Caching toggle logic
                            if let Some(pipe_idx) = find_pipe_at_cursor(&app.command, app.cursor_pos) {
                                if app.cached_pipe_index == Some(pipe_idx) {
                                    app.cached_pipe_index = None; app.cached_output = None;
                                } else {
                                    app.cached_pipe_index = Some(pipe_idx);
                                    // Evaluate the prefix to cache
                                    let segments: Vec<&str> = app.get_cmd_to_run().split('|').collect();
                                    let prefix = segments[..=pipe_idx].join("|");
                                    let eval_env = app.config.eval_environment.clone().unwrap_or_else(|| vec!["bash".to_string(), "-c".to_string()]);
                                    let out = Command::new(&eval_env[0]).args(&eval_env[1..]).arg(&prefix).output().ok();
                                    if let Some(out) = out { app.cached_output = Some(String::from_utf8_lossy(&out.stdout).to_string()); }
                                }
                            }
                        }
                        _ => {}
                    },
                    _ => match key.code {
                        KeyCode::Esc => app.active_menu = ActiveMenu::Main,
                        KeyCode::Up => {
                            let i = match app.list_state.selected() { Some(i) if i > 0 => i - 1, _ => 0 };
                            app.list_state.select(Some(i));
                        }
                        KeyCode::Down => {
                            let len = match app.active_menu {
                                ActiveMenu::History => app.history.len(),
                                ActiveMenu::Bookmarks => app.bookmarks.len(),
                                ActiveMenu::Snippets => app.config.snippets.len(),
                                ActiveMenu::HelpViewers => app.config.help_viewers.len(),
                                ActiveMenu::OutputViewers => app.config.output_viewers.len(),
                                _ => 0
                            };
                            let i = match app.list_state.selected() { Some(i) if i < len - 1 => i + 1, _ => len.saturating_sub(1) };
                            app.list_state.select(Some(i));
                        }
                        KeyCode::Enter => {
                            let selected_cmd = match app.active_menu {
                                ActiveMenu::History => app.history.get(app.list_state.selected().unwrap_or(0)).cloned(),
                                ActiveMenu::Bookmarks => app.bookmarks.get(app.list_state.selected().unwrap_or(0)).cloned(),
                                ActiveMenu::Snippets => {
                                    let keys: Vec<_> = app.config.snippets.keys().collect();
                                    app.config.snippets.get(keys.get(app.list_state.selected().unwrap_or(0)).unwrap_or(&&"".to_string())).cloned()
                                }
                                _ => None
                            };
                            if let Some(cmd) = selected_cmd {
                                if app.active_menu == ActiveMenu::Snippets {
                                    let inserted = cmd.replace("||", "");
                                    app.command.insert_str(app.cursor_pos, &inserted);
                                    app.cursor_pos += cmd.find("||").unwrap_or(inserted.len());
                                } else {
                                    app.command = cmd; app.cursor_pos = app.command.len();
                                }
                            }
                            app.active_menu = ActiveMenu::Main;
                        }
                        KeyCode::Char(c) if app.active_menu == ActiveMenu::HelpViewers || app.active_menu == ActiveMenu::OutputViewers => {
                            let viewer = if app.active_menu == ActiveMenu::HelpViewers { app.config.help_viewers.get(&c) } else { app.config.output_viewers.get(&c) };
                            if let Some(v) = viewer {
                                let cmd = if app.active_menu == ActiveMenu::HelpViewers {
                                    let word = get_word_at_cursor(&app.command, app.cursor_pos);
                                    v.replace("??", word)
                                } else {
                                    let mut temp_file = std::env::temp_dir().join("pipr_output");
                                    let _ = fs::write(&temp_file, &app.stdout);
                                    format!("{} {}", v, temp_file.display())
                                };
                                let _ = terminal.backend_mut().execute(LeaveAlternateScreen);
                                let _ = disable_raw_mode();
                                let _ = Command::new("bash").arg("-c").arg(&cmd).status();
                                let _ = enable_raw_mode();
                                let _ = terminal.backend_mut().execute(EnterAlternateScreen);
                                app.active_menu = ActiveMenu::Main;
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
    }
}

fn find_pipe_at_cursor(cmd: &str, cursor: usize) -> Option<usize> {
    let mut pipe_idx = 0;
    for (i, c) in cmd.chars().enumerate() {
        if c == '|' {
            if i == cursor { return Some(pipe_idx); }
            pipe_idx += 1;
        }
    }
    None
}

fn get_word_at_cursor(cmd: &str, cursor: usize) -> &str {
    let start = cmd[..cursor].rfind(|c: char| c.is_whitespace() || c == '|').map(|i| i + 1).unwrap_or(0);
    let end = cmd[cursor..].find(|c: char| c.is_whitespace() || c == '|').map(|i| i + cursor).unwrap_or(cmd.len());
    &cmd[start..end]
}

fn ui(f: &mut Frame, app: &App) {
    let chunks = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(app.command.lines().count().max(1) as u16 + 2), Constraint::Min(0)]).split(f.size());
    let mut title = format!(" Command {} ", if app.autoeval { "[Autoeval]" } else { "" });
    if app.cached_pipe_index.is_some() { title.push_str("[Caching] "); }
    f.render_widget(Paragraph::new(app.command.as_str()).block(Block::default().borders(Borders::ALL).title(title)), chunks[0]);

    // Cursor position
    let mut cursor_x = 0; let mut cursor_y = 0; let mut cur = 0;
    for (i, line) in app.command.lines().enumerate() {
        if cur + line.len() >= app.cursor_pos { cursor_x = app.cursor_pos - cur; cursor_y = i; break; }
        cur += line.len() + 1;
    }
    if app.command.ends_with('\n') && app.cursor_pos == app.command.len() {
        cursor_y = app.command.lines().count(); cursor_x = 0;
    }
    f.set_cursor(chunks[0].x + 1 + cursor_x as u16, chunks[0].y + 1 + cursor_y as u16);

    let output_chunks = if app.exit_code != Some(0) && !app.stderr.is_empty() {
        Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage(50), Constraint::Percentage(50)]).split(chunks[1])
    } else { vec![chunks[1]] };
    f.render_widget(Paragraph::new(app.stdout.as_str()).block(Block::default().borders(Borders::ALL).title(" Output ")), output_chunks[0]);
    if output_chunks.len() > 1 {
        f.render_widget(Paragraph::new(app.stderr.as_str()).block(Block::default().borders(Borders::ALL).title(" Stderr ")), output_chunks[1]);
    }

    let help_text = "Help: F1";
    f.render_widget(Paragraph::new(help_text), Rect::new(f.size().width - help_text.len() as u16 - 2, f.size().height - 1, help_text.len() as u16, 1));

    if app.active_menu != ActiveMenu::Main {
        let area = centered_rect(80, 80, f.size());
        f.render_widget(Clear, area);
        let (title, items) = match app.active_menu {
            ActiveMenu::Help => (" Help ", vec!["F1: Help", "F2: Autoeval", "F4: History", "F5: Help viewer", "F6: Output viewer", "F7: Cache pipe", "Ctrl+S: Bookmark", "Ctrl+B: Bookmarks", "Ctrl+V: Snippets", "Esc: Back"]),
            ActiveMenu::History => (" History ", app.history.iter().map(|s| s.as_str()).collect()),
            ActiveMenu::Bookmarks => (" Bookmarks ", app.bookmarks.iter().map(|s| s.as_str()).collect()),
            ActiveMenu::Snippets => (" Snippets ", app.config.snippets.iter().map(|(k, v)| format!("{}: {}", k, v)).collect::<Vec<_>>().iter().map(|s| s.as_str()).collect()),
            ActiveMenu::HelpViewers => (" Open in ", app.config.help_viewers.iter().map(|(k, v)| format!("{}: {}", k, v)).collect::<Vec<_>>().iter().map(|s| s.as_str()).collect()),
            ActiveMenu::OutputViewers => (" Open in ", app.config.output_viewers.iter().map(|(k, v)| format!("{}: {}", k, v)).collect::<Vec<_>>().iter().map(|s| s.as_str()).collect()),
            _ => ("", vec![])
        };
        let list_items: Vec<ListItem> = items.iter().map(|i| ListItem::new(*i)).collect();
        let list = List::new(list_items).block(Block::default().borders(Borders::ALL).title(title)).highlight_style(Style::default().add_modifier(Modifier::BOLD)).highlight_symbol(">>");
        // We should use the state but for simplicity...
        f.render_widget(list, area);
    }
}

fn centered_rect(px: u16, py: u16, r: Rect) -> Rect {
    let v = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage((100-py)/2), Constraint::Percentage(py), Constraint::Percentage((100-py)/2)]).split(r);
    Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage((100-px)/2), Constraint::Percentage(px), Constraint::Percentage((100-px)/2)]).split(v[1])[1]
}
